import java.util.Scanner;
abstract class Staff { protected String name,department; protected double salary; Staff(String n,String d,double s){name=n;department=d;salary=s;} abstract double calculateSalary(); void show(){System.out.println(name+" | "+department+" | Final salary: "+calculateSalary());} }
class FullTimeStaff extends Staff { FullTimeStaff(String n,String d,double s){super(n,d,s);} double calculateSalary(){return salary*1.13;} }
class PartTimeStaff extends Staff { private int hours; private double rate; PartTimeStaff(String n,String d,int h,double r){super(n,d,h*r);hours=h;rate=r;} double calculateSalary(){return hours*rate*1.13;} }
public class StaffSalary { public static void main(String[] a){Scanner s=new Scanner(System.in);System.out.print("Number of staff: ");int n=s.nextInt();Staff[] staff=new Staff[n];for(int i=0;i<n;i++){System.out.print("1 Full-time, 2 Part-time: ");int type=s.nextInt();s.nextLine();System.out.print("Name: ");String name=s.nextLine();System.out.print("Department: ");String dept=s.nextLine();if(type==1){System.out.print("Monthly salary: ");staff[i]=new FullTimeStaff(name,dept,s.nextDouble());}else{System.out.print("Hours and rate/hour: ");staff[i]=new PartTimeStaff(name,dept,s.nextInt(),s.nextDouble());}}for(Staff x:staff)x.show();s.close();} }
